routerAdd("POST", "/api/jornal/documents", (event) => {
  const h = require(`${__hooks}/document_helpers.js`); const input = { companyId: event.request.formValue("companyId"), dataEpoch: event.request.formValue("dataEpoch"), source: event.request.formValue("source"), filename: event.request.formValue("filename"), contentBase64: event.request.formValue("contentBase64") }; const s = h.scope(event, input, true); const encoded = String(input.contentBase64 || ""); if (!encoded || encoded.length > 11_200_000) throw new ApiError(413, "Dokumen maksimal 8 MB")
  const bytes = h.bytesFromBase64(encoded); if (!bytes.length || bytes.length > 8_388_608) throw new ApiError(413, "Dokumen maksimal 8 MB"); const mime = h.detect(bytes); const filename = String(input.filename || "dokumen").replace(/[^a-zA-Z0-9._ -]/g, "_").slice(0, 255); const hash = $security.sha256(encoded)
  let duplicate = null; try { duplicate = $app.findFirstRecordByFilter("document_inbox", "tenant_id = {:tenant} && company_id = {:company} && data_epoch = {:epoch} && sha256 = {:hash} && status != 'ARCHIVED'", { tenant: s.tenantId, company: s.companyId, epoch: s.epoch, hash }) } catch { /* unique content not found */ }
  const uploaded = event.findUploadedFiles("file"); if (!uploaded || !uploaded.length) throw new ApiError(400, "File dokumen wajib diisi"); const record = new Record($app.findCollectionByNameOrId("document_inbox"), { tenant_id: s.tenantId, company_id: s.companyId, data_epoch: s.epoch, source: ["CAMERA", "UPLOAD", "SHARE_TARGET"].includes(String(input.source)) ? String(input.source) : "UPLOAD", filename, mime, byte_size: bytes.length, sha256: hash, file: uploaded[0], content_base64: encoded, status: "UNPROCESSED", duplicate_of_id: duplicate ? duplicate.id : "", revision: 1 }); $app.save(record)
  return event.json(201, { document: h.response(record), duplicate: duplicate ? h.response(duplicate) : null })
}, $apis.requireAuth())

routerAdd("GET", "/api/jornal/documents", (event) => { const h = require(`${__hooks}/document_helpers.js`); const query = event.requestInfo().query || {}; const s = h.scope(event, query, false); let filter = "tenant_id = {:tenant} && company_id = {:company} && data_epoch = {:epoch}"; const params = { tenant: s.tenantId, company: s.companyId, epoch: s.epoch }; if (query.status) { filter += " && status = {:status}"; params.status = String(query.status) }; const records = h.findAll($app, "document_inbox", filter, "-created,id", params); return event.json(200, { items: records.map(h.response) }) }, $apis.requireAuth())

routerAdd("GET", "/api/jornal/documents/search", (event) => { const h = require(`${__hooks}/document_helpers.js`); const query = event.requestInfo().query || {}; const s = h.scope(event, query, false); const needle = String(query.search || "").trim().toLowerCase(); if (needle.length < 2) return event.json(200, { items: [] }); const records = h.findAll($app, "document_inbox", "tenant_id = {:tenant} && company_id = {:company} && data_epoch = {:epoch} && status != 'ARCHIVED'", "-created,id", { tenant: s.tenantId, company: s.companyId, epoch: s.epoch }); const items = []; for (const record of records) { let result = {}; try { const extraction = $app.findFirstRecordByFilter("document_extractions", "tenant_id = {:tenant} && company_id = {:company} && data_epoch = {:epoch} && document_id = {:document}", "-created", 1, 0, { tenant: s.tenantId, company: s.companyId, epoch: s.epoch, document: record.id }); result = h.json(extraction, "result", {}) } catch { /* no extraction */ }; const searchable = [record.getString("filename"), result.documentType, result.merchantName, result.senderName, result.recipientName, result.reference, result.description].filter(Boolean).join(" ").toLowerCase(); if (searchable.includes(needle)) items.push({ document: h.response(record), summary: { documentType: result.documentType || null, merchantName: result.merchantName || null, description: result.description || null } }); if (items.length >= 20) break }; return event.json(200, { items }) }, $apis.requireAuth())

routerAdd("GET", "/api/jornal/documents/{id}", (event) => { const h = require(`${__hooks}/document_helpers.js`); const query = event.requestInfo().query || {}; const s = h.scope(event, query, false); const record = h.owned($app, "document_inbox", event.request.pathValue("id"), s, "Dokumen"); let extraction = null; try { extraction = $app.findFirstRecordByFilter("document_extractions", "tenant_id = {:tenant} && company_id = {:company} && data_epoch = {:epoch} && document_id = {:document}", "-created", 1, 0, { tenant: s.tenantId, company: s.companyId, epoch: s.epoch, document: record.id }) } catch { /* none */ }; let linkedInvoiceId = null; if (record.getString("linked_payment_id")) { try { linkedInvoiceId = $app.findRecordById("invoice_payments", record.getString("linked_payment_id")).getString("invoice_id") } catch { /* retained document with unavailable payment */ } }; return event.json(200, { document: h.response(record), linkedInvoiceId, contentBase64: h.json(record, "content_base64", record.getString("content_base64")), extraction: extraction ? { id: extraction.id, result: h.json(extraction, "result", {}), warnings: h.json(extraction, "warnings", []), model: extraction.getString("model"), createdAt: extraction.getString("created") } : null }) }, $apis.requireAuth())

routerAdd("POST", "/api/jornal/documents/{id}/extract", (event) => { const h = require(`${__hooks}/document_helpers.js`); const input = h.body(event); const s = h.scope(event, input, true); const document = h.owned($app, "document_inbox", event.request.pathValue("id"), s, "Dokumen"); if ($os.getenv("JORNAL_AI_CAPTURE_ENABLED") !== "true") throw new ApiError(503, "Pemindaian AI sedang dinonaktifkan"); const key = String(input.requestKey || ""); if (!key) throw new ApiError(400, "requestKey wajib diisi"); let job; try { job = $app.findFirstRecordByFilter("ai_jobs", "tenant_id = {:tenant} && company_id = {:company} && data_epoch = {:epoch} && request_key = {:key}", { tenant: s.tenantId, company: s.companyId, epoch: s.epoch, key }) } catch { const start = `${new Date().toISOString().slice(0, 10)} 00:00:00.000Z`; const daily = $app.findRecordsByFilter("ai_jobs", "tenant_id = {:tenant} && created >= {:start}", "", 0, 0, { tenant: s.tenantId, start }).length; const limit = Math.max(1, Number($os.getenv("JORNAL_AI_DAILY_SCAN_LIMIT") || 20)); if (daily >= limit) throw new ApiError(429, "Batas scan AI harian tercapai"); job = new Record($app.findCollectionByNameOrId("ai_jobs"), { tenant_id: s.tenantId, company_id: s.companyId, data_epoch: s.epoch, document_id: document.id, request_key: key, input_hash: document.getString("sha256"), schema_version: "document-extraction-v1", status: "QUEUED", attempt_count: 0, generation: 1 }); $app.save(job) }; return event.json(202, { job: { id: job.id, status: job.getString("status"), attemptCount: job.getInt("attempt_count"), errorCode: job.getString("error_code") || null } }) }, $apis.requireAuth())

routerAdd("GET", "/api/jornal/ai-jobs/{id}", (event) => { const h = require(`${__hooks}/document_helpers.js`); const query = event.requestInfo().query || {}; const s = h.scope(event, query, false); const job = h.owned($app, "ai_jobs", event.request.pathValue("id"), s, "Job AI"); let result = null; if (job.getString("extraction_id")) { try { const extraction = h.owned($app, "document_extractions", job.getString("extraction_id"), s, "Hasil ekstraksi"); result = h.json(extraction, "result", {}) } catch { /* incomplete */ } }; return event.json(200, { job: { id: job.id, documentId: job.getString("document_id"), status: job.getString("status"), attemptCount: job.getInt("attempt_count"), errorCode: job.getString("error_code") || null, result } }) }, $apis.requireAuth())

routerAdd("POST", "/api/jornal/documents/{id}/archive", (event) => { const h = require(`${__hooks}/document_helpers.js`); const input = h.body(event); const s = h.scope(event, input, true); const record = h.owned($app, "document_inbox", event.request.pathValue("id"), s, "Dokumen"); if (record.getInt("revision") !== Number(input.expectedRevision)) throw new ApiError(409, "Dokumen telah berubah"); record.set("status", "ARCHIVED"); record.set("revision", record.getInt("revision") + 1); $app.save(record); const jobs = $app.findRecordsByFilter("ai_jobs", "document_id = {:document} && (status = 'QUEUED' || status = 'RUNNING')", "", 0, 0, { document: record.id }); jobs.forEach((job) => { job.set("status", "CANCELLED"); $app.save(job) }); return event.json(200, { document: h.response(record) }) }, $apis.requireAuth())

routerAdd("GET", "/api/jornal/documents/{id}/invoice-candidates", (event) => { const h = require(`${__hooks}/document_helpers.js`); const invoiceHelpers = require(`${__hooks}/invoice_helpers.js`); const query = event.requestInfo().query || {}; const s = h.scope(event, query, false); h.owned($app, "document_inbox", event.request.pathValue("id"), s, "Dokumen"); const amount = Number(query.amount || 0); if (!Number.isSafeInteger(amount) || amount <= 0) return event.json(200, { items: [] }); const invoices = invoiceHelpers.findAllRecords($app, "invoices", "tenant_id = {:tenant} && company_id = {:company} && data_epoch = {:epoch} && status = 'UNPAID' && grand_total = {:amount} && deleted_at = ''", "due_date,id", { tenant: s.tenantId, company: s.companyId, epoch: s.epoch, amount }); return event.json(200, { items: invoices.slice(0, 20).map(invoiceHelpers.invoiceResponse) }) }, $apis.requireAuth())

routerAdd("POST", "/api/jornal/documents/{id}/confirm", (event) => {
  const h = require(`${__hooks}/document_helpers.js`); const input = h.body(event); const s = h.scope(event, input, true); const key = String(input.commandKey || ""); if (!key || key.length > 100) throw new ApiError(400, "commandKey wajib diisi")
  const action = "CONFIRM_DOCUMENT"; const hash = h.commandHash(action, input); let result; let status = 200
  $app.runInTransaction((tx) => {
    const replay = h.replayCommand(tx, s, key, action, hash); if (replay) { result = replay.body; status = replay.status; return }
    const document = h.owned(tx, "document_inbox", event.request.pathValue("id"), s, "Dokumen"); if (document.getString("status") === "ARCHIVED") throw new ApiError(409, "Dokumen telah diarsipkan"); if (document.getInt("revision") !== Number(input.expectedRevision)) throw new ApiError(409, "Dokumen telah berubah")
    const mode = String(input.mode || "CREATE_TRANSACTION"); if (!["CREATE_TRANSACTION", "LINK_TRANSACTION", "MATCH_INVOICE"].includes(mode)) throw new ApiError(400, "Mode konfirmasi tidak valid")
    const transactionId = String(input.transactionId || ""); if (!transactionId || transactionId.length > 100) throw new ApiError(400, "transactionId wajib diisi")
    if (mode === "MATCH_INVOICE") { const invoiceHelpers = require(`${__hooks}/invoice_helpers.js`); const invoice = invoiceHelpers.ownedRecord(tx, "invoices", String(input.invoiceId || ""), s.tenantId, s.companyId, s.epoch, "Invoice"); if (invoice.getString("status") !== "UNPAID") throw new ApiError(409, "Invoice tidak lagi menunggu pembayaran"); if (invoice.getInt("revision") !== Number(input.expectedInvoiceRevision)) throw new ApiError(409, "Invoice telah berubah"); const paidOn = invoiceHelpers.isoDate(input.transactionDate, "Tanggal pembayaran"); if (paidOn < invoice.getString("issue_date") || paidOn > new Date().toISOString().slice(0, 10)) throw new ApiError(400, "Tanggal pembayaran tidak valid"); if (Number(input.amount) !== invoice.getInt("grand_total")) throw new ApiError(409, "Nominal dokumen tidak cocok dengan invoice"); if (tx.findRecordsByFilter("invoice_payments", "invoice_id = {:invoice} && status = 'ACTIVE'", "", 1, 0, { invoice: invoice.id }).length) throw new ApiError(409, "Invoice sudah memiliki pembayaran aktif"); if (tx.findRecordsByFilter("jornal_records", "business_id = {:tenant} && company_id = {:company} && entity = 'transactions' && app_id = {:id}", "", 1, 0, { tenant: s.tenantId, company: s.companyId, id: transactionId }).length) throw new ApiError(409, "ID transaksi sudah digunakan"); const customer = invoiceHelpers.ownedRecord(tx, "invoice_customers", invoice.getString("customer_id"), s.tenantId, s.companyId, s.epoch, "Pelanggan"); const now = new Date().toISOString(); const invoiceMetadata = { invoiceId: invoice.id, invoiceNumber: invoice.getString("invoice_number"), customerId: customer.id, invoiceRevenueAmount: invoice.getInt("subtotal") - invoice.getInt("discount_amount") + invoice.getInt("shipping_amount"), invoiceTaxAmount: invoice.getInt("tax_amount") }; const transaction = { id: transactionId, businessId: s.tenantId, companyId: s.companyId, direction: "MONEY_IN", amount: invoice.getInt("grand_total"), currency: "IDR", transactionDate: paidOn, description: String(input.description || `Pelunasan invoice ${invoice.getString("invoice_number")}`).slice(0, 500), notes: "", categoryId: null, paymentMethod: "BANK_TRANSFER", supplierCustomer: customer.getString("name"), tags: "invoice,dokumen", accountId: input.accountId ? String(input.accountId) : null, transferAccountId: null, attachmentName: null, attachmentDataUrl: null, documentId: document.id, ...invoiceMetadata, classification: "REVENUE", taxClassification: "REVENUE", businessRelevance: "BUSINESS", classificationSource: "USER", classificationConfidence: 1, reviewStatus: "ACCEPTED", createdAt: now, updatedAt: now }; if (transaction.accountId) { try { tx.findFirstRecordByFilter("jornal_records", "business_id = {:tenant} && company_id = {:company} && data_epoch = {:epoch} && entity = 'accounts' && app_id = {:id}", { tenant: s.tenantId, company: s.companyId, epoch: s.epoch, id: transaction.accountId }) } catch { throw new ApiError(400, "Rekening tidak berada pada company ini") } }; const ledger = new Record(tx.findCollectionByNameOrId("jornal_records"), { business_id: s.tenantId, company_id: s.companyId, data_epoch: s.epoch, entity: "transactions", app_id: transactionId, payload: transaction, revision: 1 }); tx.save(ledger); const payment = new Record(tx.findCollectionByNameOrId("invoice_payments"), { tenant_id: s.tenantId, company_id: s.companyId, data_epoch: s.epoch, invoice_id: invoice.id, amount: invoice.getInt("grand_total"), paid_on: paidOn, account_id: String(transaction.accountId || ""), ledger_transaction_id: transactionId, origin: "CREATED", status: "ACTIVE", lifecycle: "CURRENT", reference: "Dokumen inbox", revision: 1 }); tx.save(payment); transaction.invoicePaymentId = payment.id; ledger.set("payload", transaction); tx.save(ledger); invoice.set("status", "PAID"); invoice.set("paid_at", now); invoice.set("revision", invoice.getInt("revision") + 1); tx.save(invoice); const reminders = tx.findRecordsByFilter("invoice_reminders", "invoice_id = {:invoice} && status != 'RESOLVED'", "", 0, 0, { invoice: invoice.id }); reminders.forEach((reminder) => { reminder.set("status", "RESOLVED"); reminder.set("resolved_at", now); tx.save(reminder) }); document.set("status", "LINKED"); document.set("linked_transaction_id", transactionId); document.set("linked_payment_id", payment.id); document.set("link_origin", "INVOICE_PAYMENT"); document.set("revision", document.getInt("revision") + 1); tx.save(document); result = { document: h.response(document), ledgerTransaction: transaction, ledgerRevision: 1, invoice: invoiceHelpers.invoiceResponse(invoice), payment: invoiceHelpers.paymentResponse(payment) }; h.saveCommand(tx, s, key, action, hash, status, result); return }
    let ledger; let transaction; let originalLedgerSnapshot = null
    if (mode === "CREATE_TRANSACTION") {
      const direction = String(input.direction || ""); if (!["MONEY_IN", "MONEY_OUT"].includes(direction)) throw new ApiError(400, "Arah transaksi tidak valid")
      const amount = Number(input.amount); if (!Number.isSafeInteger(amount) || amount <= 0 || amount > 1_000_000_000_000) throw new ApiError(400, "Nominal transaksi tidak valid")
      const transactionDate = String(input.transactionDate || ""); if (!/^\d{4}-\d{2}-\d{2}$/.test(transactionDate) || Number.isNaN(Date.parse(`${transactionDate}T00:00:00Z`)) || transactionDate > new Date().toISOString().slice(0, 10)) throw new ApiError(400, "Tanggal transaksi tidak valid")
      if (tx.findRecordsByFilter("jornal_records", "business_id = {:tenant} && company_id = {:company} && data_epoch = {:epoch} && entity = 'transactions' && app_id = {:id}", "", 1, 0, { tenant: s.tenantId, company: s.companyId, epoch: s.epoch, id: transactionId }).length) throw new ApiError(409, "ID transaksi sudah digunakan")
      const now = new Date().toISOString(); const classification = direction === "MONEY_IN" ? "REVENUE" : "EXPENSE"
      transaction = { id: transactionId, businessId: s.tenantId, companyId: s.companyId, direction, amount, currency: "IDR", transactionDate, description: String(input.description || "Dokumen transaksi").trim().slice(0, 500), notes: "", categoryId: input.categoryId ? String(input.categoryId) : null, paymentMethod: String(input.paymentMethod || "OTHER").slice(0, 80), supplierCustomer: input.supplierCustomer ? String(input.supplierCustomer).slice(0, 255) : null, tags: "dokumen", accountId: input.accountId ? String(input.accountId) : null, transferAccountId: null, attachmentName: null, attachmentDataUrl: null, documentId: document.id, classification, taxClassification: classification, businessRelevance: "BUSINESS", classificationSource: "USER", classificationConfidence: 1, reviewStatus: "ACCEPTED", createdAt: now, updatedAt: now }
      if (transaction.accountId) { try { tx.findFirstRecordByFilter("jornal_records", "business_id = {:tenant} && company_id = {:company} && data_epoch = {:epoch} && entity = 'accounts' && app_id = {:id}", { tenant: s.tenantId, company: s.companyId, epoch: s.epoch, id: transaction.accountId }) } catch { throw new ApiError(400, "Rekening tidak berada pada company ini") } }
      ledger = new Record(tx.findCollectionByNameOrId("jornal_records"), { business_id: s.tenantId, company_id: s.companyId, data_epoch: s.epoch, entity: "transactions", app_id: transactionId, payload: transaction, revision: 1 }); tx.save(ledger)
    } else {
      try { ledger = tx.findFirstRecordByFilter("jornal_records", "business_id = {:tenant} && company_id = {:company} && data_epoch = {:epoch} && entity = 'transactions' && app_id = {:id} && deleted_at = ''", { tenant: s.tenantId, company: s.companyId, epoch: s.epoch, id: transactionId }) } catch { throw new ApiError(404, "Transaksi tidak ditemukan") }
      if (ledger.getInt("revision") !== Number(input.expectedTransactionRevision)) throw new ApiError(409, "Transaksi telah berubah"); transaction = h.json(ledger, "payload", {}); if (transaction.documentId) throw new ApiError(409, "Transaksi sudah terhubung ke dokumen lain"); if (transaction.invoicePaymentId || transaction.taxSettlementId || transaction.receivableTransactionId) throw new ApiError(409, "Transaksi dikelola oleh proses lain"); originalLedgerSnapshot = transaction; transaction = { ...transaction, documentId: document.id, updatedAt: new Date().toISOString() }; ledger.set("payload", transaction); ledger.set("revision", ledger.getInt("revision") + 1); tx.save(ledger)
    }
    document.set("status", "LINKED"); document.set("linked_transaction_id", transactionId); document.set("link_origin", mode === "CREATE_TRANSACTION" ? "CREATED" : "LINKED"); document.set("original_ledger_snapshot", originalLedgerSnapshot); document.set("revision", document.getInt("revision") + 1); tx.save(document)
    result = { document: h.response(document), ledgerTransaction: transaction, ledgerRevision: ledger.getInt("revision") }; h.saveCommand(tx, s, key, action, hash, status, result)
  })
  return event.json(status, result)
}, $apis.requireAuth())

routerAdd("POST", "/api/jornal/documents/{id}/unlink", (event) => { const h = require(`${__hooks}/document_helpers.js`); const input = h.body(event); const s = h.scope(event, input, true); const key = String(input.commandKey || ""); const reason = String(input.reason || "").trim(); if (!key || key.length > 100) throw new ApiError(400, "commandKey wajib diisi"); if (!reason || reason.length > 500) throw new ApiError(400, "Alasan koreksi wajib diisi"); const action = "UNLINK_DOCUMENT"; const hash = h.commandHash(action, input); let result
  $app.runInTransaction((tx) => { const replay = h.replayCommand(tx, s, key, action, hash); if (replay) { result = replay.body; return }; const document = h.owned(tx, "document_inbox", event.request.pathValue("id"), s, "Dokumen"); if (document.getString("status") !== "LINKED") throw new ApiError(409, "Dokumen tidak sedang tertaut"); if (document.getInt("revision") !== Number(input.expectedRevision)) throw new ApiError(409, "Dokumen telah berubah"); let ledger; try { ledger = tx.findFirstRecordByFilter("jornal_records", "business_id = {:tenant} && company_id = {:company} && data_epoch = {:epoch} && entity = 'transactions' && app_id = {:id}", { tenant: s.tenantId, company: s.companyId, epoch: s.epoch, id: document.getString("linked_transaction_id") }) } catch { throw new ApiError(409, "Transaksi tertaut tidak ditemukan") }; let transaction = h.json(ledger, "payload", {}); const deleted = document.getString("link_origin") === "CREATED"; if (deleted) { transaction = { ...transaction, lifecycle: "REVERSED", reversedAt: new Date().toISOString(), reversalReason: reason, updatedAt: new Date().toISOString() }; ledger.set("deleted_at", new Date().toISOString()) } else { const original = h.json(document, "original_ledger_snapshot", null); if (!original) throw new ApiError(409, "Snapshot transaksi sebelum tautan tidak tersedia"); transaction = original }; ledger.set("payload", transaction); ledger.set("revision", ledger.getInt("revision") + 1); tx.save(ledger); document.set("status", "REVIEW_READY"); document.set("linked_transaction_id", ""); document.set("unlink_reason", reason); document.set("revision", document.getInt("revision") + 1); tx.save(document); result = { document: h.response(document), ledgerTransaction: transaction, ledgerDeleted: deleted }; h.saveCommand(tx, s, key, action, hash, 200, result) }); return event.json(200, result)
}, $apis.requireAuth())
